package com.portfolio.service;
import com.portfolio.config.ErrorLoggingService; import com.portfolio.domain.*; import com.portfolio.dto.TransactionDto; import com.portfolio.repository.*; import org.springframework.dao.*; import org.springframework.retry.annotation.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.time.format.DateTimeFormatter;
@Service public class PortfolioTransactionService {
 public record TransactionResult(String transactionId,boolean success,String message){} private final PortfolioRepository portfolios; private final TransactionRepository transactions; private final AuditLogRepository audits; private final ErrorLoggingService errors; private final PortfolioValidationService validation;
 public PortfolioTransactionService(PortfolioRepository p,TransactionRepository t,AuditLogRepository a,ErrorLoggingService e,PortfolioValidationService v){portfolios=p;transactions=t;audits=a;errors=e;validation=v;}
 @Transactional @Retryable(retryFor={TransientDataAccessException.class,CannotAcquireLockException.class},maxAttempts=3,backoff=@Backoff(delay=100))
 public TransactionResult process(Transaction trn){Portfolio p=null;String before="";try{if(trn.getPortfolioId()==null||trn.getPortfolioId().isBlank())throw new BusinessException("E008","Portfolio ID is required");p=portfolios.findById(trn.getPortfolioId()).orElseThrow(()->new BusinessException("E008","Invalid Portfolio ID: "+trn.getPortfolioId()));if(trn.getTransactionType()==null)throw new BusinessException("E008","Invalid Transaction Type: null");validateAmounts(trn);before=state(p);switch(trn.getTransactionType()){case BUY-> {p.setTotalUnits(p.getTotalUnits().add(z(trn.getQuantity())));p.setTotalCost(p.getTotalCost().add(z(trn.getAmount())));}case SELL->{if(p.getTotalUnits().compareTo(z(trn.getQuantity()))<0)throw new BusinessException("E008","Insufficient units for sale");p.setTotalUnits(p.getTotalUnits().subtract(z(trn.getQuantity())));p.setTotalCost(p.getTotalCost().subtract(z(trn.getAmount())));}case FEE->p.setTotalCost(p.getTotalCost().subtract(z(trn.getAmount())));case TRANSFER->throw new UnsupportedOperationException("Transfer processing not implemented");}p.setLastTransDate(trn.getTransactionDate()==null?LocalDate.now():trn.getTransactionDate());p.setLastUser(trn.getProcessUser());trn.setStatus(TransactionStatus.DONE);trn.setProcessDate(LocalDateTime.now());transactions.save(trn);portfolios.save(p);audit(trn,p,AudiStatusFor(trn.getTransactionType()),before);return new TransactionResult(trn.getTransactionId(),true,"Processed");}catch(BusinessException ex){if(trn!=null){trn.setStatus(TransactionStatus.FAILED);if(trn.getTransactionId()!=null)transactions.save(trn);}errors.log("PORTTRAN",ErrorType.APPLICATION,ErrorSeverity.WARNING,"PR",ex.getMessage(),"");if(p!=null)audit(trn,p,AuditStatus.FAILURE,before);throw ex;}}
 private AuditStatus AudiStatusFor(TransactionType t){return AuditStatus.SUCCESS;} private BigDecimal z(BigDecimal v){return v==null?BigDecimal.ZERO:v;} public void validateAmounts(Transaction t){if(z(t.getQuantity()).compareTo(BigDecimal.ZERO)<=0)throw new BusinessException("E008","Quantity must be greater than zero");if(t.getTransactionType()!=TransactionType.TRANSFER&&z(t.getPrice()).compareTo(BigDecimal.ZERO)<=0)throw new BusinessException("E008","Price must be greater than zero");if(t.getTransactionType()!=TransactionType.TRANSFER&&z(t.getAmount()).compareTo(BigDecimal.ZERO)<=0)throw new BusinessException("E008","Amount must be greater than zero");}
 private String state(Portfolio p){String s=p.getPortfolioId()+"|"+p.getTotalUnits()+"|"+p.getTotalCost();return s.length()>100?s.substring(0,100):s;} private void audit(Transaction t,Portfolio p,AuditStatus st,String before){AuditLog a=new AuditLog();a.setAudTimestamp(LocalDateTime.now());a.setProgram("PORTTRAN");a.setAudType(AuditType.TRAN);a.setAction(switch(t.getTransactionType()){case BUY->AuditAction.CREATE;case SELL->AuditAction.DELETE;default->AuditAction.UPDATE;});a.setStatus(st);a.setPortfolioId(p.getPortfolioId());a.setAccountNo(p.getAccountNo());a.setBeforeImage(before);a.setMessage("Transaction: "+t.getTransactionType().getCode()+" Amount: "+t.getAmount()+" Units: "+t.getQuantity());audits.save(a);}
 @Transactional public Transaction createPending(TransactionDto d){Transaction t=new Transaction();LocalDate date=d.getTransactionDate()==null?LocalDate.now():d.getTransactionDate();LocalTime time=d.getTransactionTime()==null?LocalTime.now():d.getTransactionTime();String seq="000001";t.setTransactionDate(date);t.setTransactionTime(time);t.setPortfolioId(d.getPortfolioId());t.setSequenceNo(seq);t.setTransactionId(date.format(DateTimeFormatter.BASIC_ISO_DATE)+time.format(DateTimeFormatter.ofPattern("HHmmss"))+d.getPortfolioId()+seq);t.setInvestmentId(d.getInvestmentId());t.setTransactionType(TransactionType.fromCode(d.getTransactionType()));t.setQuantity(d.getQuantity());t.setPrice(d.getPrice());t.setAmount(d.getAmount());t.setCurrencyCode(d.getCurrencyCode());t.setStatus(TransactionStatus.PENDING);t.setProcessUser(d.getProcessUser());return transactions.save(t);}
 public TransactionResult applyPending(Transaction t){return process(t);}
}
